def _compute_wait(attempt: int, backoff_seconds: tuple[int, ...]) -> float:
    """计算第 attempt 次重试的等待时间（含随机抖动）。"""
    backoff_idx = min(attempt, len(backoff_seconds) - 1)
    return backoff_seconds[backoff_idx] + random.uniform(0, 2)

